sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float count;
uniform float2 stretch;
uniform float2 offset;
half4 main(float2 coord) {
    float2 dims = max(abs(stretch), float2(0.01)) * size.y / max(count, 1.0);
    float2 o = size * 0.5 + offset;
    float2 n = floor((coord - o) / dims);
    float4 sum = float4(0.0);
    for (int j = 0; j < 4; j++) {
        for (int i = 0; i < 4; i++) {
            sum += float4(image.eval(o + (n + (float2(float(i), float(j)) + 0.5) / 4.0) * dims));
        }
    }
    return half4(sum / 16.0);
}
